-- Training planning (M9, docs/domains/training-planning.md): exercises get a phase of the unit
-- (Lösen, Arbeiten, Entspannen), a typical duration, an intensity, prerequisites, equipment, who
-- they suit, a one-sentence summary and their sources as data. The discipline column now means
-- the library; poles and cavaletti become their own library (used on hall, arena, lunge and
-- jumping days). The 42 global rows get their metadata; the sources are the pages the SQL
-- comments of 0250 and 0280 name. Global rows only; a later catalog migration adds rows.
ALTER TABLE exercises
    ADD COLUMN phase     text NOT NULL DEFAULT 'main' CHECK (phase IN ('warmup', 'main', 'cooldown', 'any')),
    ADD COLUMN minutes   integer CHECK (minutes > 0 AND minutes <= 120),
    ADD COLUMN intensity text NOT NULL DEFAULT 'normal' CHECK (intensity IN ('light', 'normal', 'demanding')),
    ADD COLUMN requires  uuid[] NOT NULL DEFAULT '{}',
    ADD COLUMN equipment text[] NOT NULL DEFAULT '{}',
    ADD COLUMN suits     text[] NOT NULL DEFAULT '{}',
    ADD COLUMN summary   text NOT NULL DEFAULT '',
    ADD COLUMN sources   text[] NOT NULL DEFAULT '{}';

UPDATE exercises SET discipline = 'dressage', phase = 'cooldown', minutes = 5, intensity = 'light', suits = '{young,senior}', equipment = '{}', summary = 'Prüft und fördert Losgelassenheit und Anlehnung: Das Pferd dehnt sich vorwärts-abwärts an die Hand.', sources = '{https://magazin.pferdesport-deutschland.de/project/lektion-im-fokus-09-2021/,https://www.wehorse.com/de/blog/zuegel-aus-der-hand-kauen-lassen/}', goal_tags = goal_tags || '{mobilitaet}'::text[]
WHERE id = '00000000-0000-4000-8000-000000000801' AND stable_id IS NULL;
