-- Keep tags unique after the additions above.
UPDATE exercises SET goal_tags = ARRAY(SELECT DISTINCT t FROM unnest(goal_tags) AS t ORDER BY t)
WHERE stable_id IS NULL AND id::text LIKE '00000000-0000-4000-8000-0000000008%';
